func newDistributionPointsPatchCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagScaffold bool
		flagSet      []string
		fromFile     string
		flagName     string
	)

	cmd := &cobra.Command{
		Use:   "patch [<id>]",
		Short: "Update specified distribution point object",
		Long:  "Updates the specified object configuration of a File Share Distribution Point in Jamf Pro. ID path parameter is mandatory and other fields can be updated as a whole or with minimal object.\n\nIdentify the resource by ID (positional arg), --name, . Omit ID to use a lookup flag.\n\nUse --set KEY=VALUE to update scalar fields (repeatable). Omitted fields are unchanged.\n\nAvailable fields:\n  backupDistributionPointId                    string\n  enableLoadBalancing                          boolean\n  fileSharingConnectionType                    string\n  httpsContext                                 string\n  httpsEnabled                                 boolean\n  httpsPassword                                string\n  httpsPort                                    integer\n  httpsSecurityType                            string\n  httpsUsername                                string\n  localPathToShare                             string\n  name                                         string\n  port                                         integer\n  principal                                    boolean\n  readOnlyPassword                             string\n  readOnlyUsername                             string\n  readWritePassword                            string\n  readWriteUsername                            string\n  serverName                                   string\n  shareName                                    string\n  sshPassword                                  string\n  sshUsername                                  string\n  workgroup                                    string\n\nUse --from-file or pipe JSON to stdin for complex updates (arrays, bulk changes).",
		Example: `  # Update a field by ID
  jamf-cli distribution-points patch 1 --set general.managed=true

  # Update multiple fields
  jamf-cli distribution-points patch 1 --set field1=value1 --set field2=value2

  # Update by name
  jamf-cli distribution-points patch --name "Example" --set general.managed=true

  # Patch from a file
  jamf-cli distribution-points patch 1 --from-file changes.json`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			if flagScaffold {
				return printScaffoldOutput(`{
  "backupDistributionPointId": "",
  "enableLoadBalancing": false,
  "fileSharingConnectionType": "AFP",
  "httpsContext": "JamfShare",
  "httpsEnabled": false,
  "httpsPassword": "password",
  "httpsPort": 0,
  "httpsSecurityType": "",
  "httpsUsername": "admin",
  "localPathToShare": "/",
  "name": "My distribution point",
  "port": 0,
  "principal": false,
  "readOnlyPassword": "password",
  "readOnlyUsername": "john.doe",
  "readWritePassword": "password",
  "readWriteUsername": "john.doe",
  "serverName": "My Server",
  "shareName": "My Share",
  "sshPassword": "password",
  "sshUsername": "john.doe",
  "workgroup": "WORKGROUP1"
}`, ctx.Output.Format())
			}

			// Resolve resource ID from positional arg, --name, or lookup flags
			var resolvedPatchID string
			if flagName != "" {
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/v1/distribution-points", "name", "id", flagName)
				if err != nil {
					return err
				}
				resolvedPatchID = rid
			} else if len(args) > 0 {
				resolvedPatchID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument, --name")
			}

			// Build request path
			path := "/v1/distribution-points/{id}"
			path = strings.Replace(path, "{id}", url.PathEscape(resolvedPatchID), 1)

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			// Read body from stdin if available
			var body io.Reader
			// PATCH: --set flags take priority; fall back to --from-file or stdin
			reqCtx = registry.WithContentType(reqCtx, "application/merge-patch+json")
			switch {
			case len(flagSet) > 0:
				data, err := buildMergePatchFromSet(flagSet)
				if err != nil {
					return err
				}
				body = bytes.NewReader(data)
			case fromFile != "":
				data, err := os.ReadFile(fromFile)
				if err != nil {
					return fmt.Errorf("reading input file: %w", err)
				}
				body = bytes.NewReader(data)
			default:
				stat, _ := os.Stdin.Stat()
				if (stat.Mode() & os.ModeCharDevice) == 0 {
					body = os.Stdin
				}
			}
			resp, err := ctx.Client.Do(reqCtx, "PATCH", path, body)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")
	cmd.Flags().StringArrayVar(&flagSet, "set", nil, "Set a field value in dot notation (key=value, repeatable)")
	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON merge-patch file (or pipe to stdin)")
	_ = cmd.RegisterFlagCompletionFunc("set", func(_ *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
		return []string{
			"backupDistributionPointId=", "enableLoadBalancing=", "fileSharingConnectionType=", "httpsContext=", "httpsEnabled=", "httpsPassword=", "httpsPort=", "httpsSecurityType=", "httpsUsername=", "localPathToShare=", "name=", "port=", "principal=", "readOnlyPassword=", "readOnlyUsername=", "readWritePassword=", "readWriteUsername=", "serverName=", "shareName=", "sshPassword=", "sshUsername=", "workgroup=",
		}, cobra.ShellCompDirectiveNoSpace
	})
	cmd.Flags().StringVar(&flagName, "name", "", "Look up distribution-point by name")

	return cmd
}

func newDistributionPointsApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile     string
		flagYes      bool
		flagDryRun   bool
		flagScaffold bool
	)

	cmd := &cobra.Command{
		Use:   "apply",
		Short: "Create or replace a distribution-point by name",
		Long: `Create or replace a distribution-point. Reads JSON or YAML from --from-file or stdin.

The name field in the input is used to check if the resource
already exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.`,
		Example: `  # Apply a distribution-point from a JSON file
  jamf-cli distribution-points apply --from-file distribution-point.json

  # Apply a distribution-point from a YAML file
  jamf-cli distribution-points apply --from-file distribution-point.yaml

  # Apply from stdin
  cat distribution-point.json | jamf-cli distribution-points apply

  # Apply without replacement confirmation
  jamf-cli distribution-points apply --from-file distribution-point.json --yes

  # Preview what would happen
  jamf-cli distribution-points apply --from-file distribution-point.json --dry-run`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			reqCtx := cmd.Context()

			if flagScaffold {
				return printScaffoldOutput(`{
  "backupDistributionPointId": "",
  "enableLoadBalancing": false,
  "fileSharingConnectionType": "AFP",
  "httpsContext": "JamfShare",
  "httpsEnabled": false,
  "httpsPassword": "password",
  "httpsPort": 0,
  "httpsSecurityType": "",
  "httpsUsername": "admin",
  "localPathToShare": "/",
  "name": "My distribution point",
  "port": 0,
  "principal": false,
  "readOnlyPassword": "password",
  "readOnlyUsername": "john.doe",
  "readWritePassword": "password",
  "readWriteUsername": "john.doe",
  "serverName": "My Server",
  "shareName": "My Share",
  "sshPassword": "password",
  "sshUsername": "john.doe",
  "workgroup": "WORKGROUP1"
}`, ctx.Output.Format())
			}

			// Read input (JSON or YAML)
			data, err := readApplyInput(fromFile)
			if err != nil {
				return err
			}
			data, err = normalizeInputToJSON(data)
			if err != nil {
				return err
			}

			// Extract name from JSON input
			name, err := extractJSONField(data, "name")
			if err != nil {
				return fmt.Errorf("input must include a %q field: %w", "name", err)
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveNameToIDForApply(reqCtx, ctx.Client, "/v1/distribution-points", "name", "id", name, noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create
				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create distribution-point %q\n", name)
					return nil
				}
				resp, err := ctx.Client.Do(reqCtx, "POST", "/v1/distribution-points", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				fmt.Fprintf(os.Stderr, "Created distribution-point %q\n", name)
				return ctx.Output.PrintResponse(resp)
			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace distribution-point %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("distribution-point %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "distribution-point %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			updatePath := strings.Replace("/v1/distribution-points/{id}", "{id}", url.PathEscape(id), 1)
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced distribution-point %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON or YAML input file (or pipe to stdin)")
	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")

	return cmd
}
